export function getLocalProvinces() {
  return REGION_DATA.filter((item) => item.level === 1);
}

export function getLocalCities(provinceCode) {
  return REGION_DATA.filter((item) => item.level === 2 && item.parentCode === String(provinceCode || ''));
}

export function getLocalDistricts(cityCode) {
  return REGION_DATA.filter((item) => item.level === 3 && item.parentCode === String(cityCode || ''));
}
